int a = 0;
int b = 0;
int p = 0;
int q = 0;
int r = 0;
int s = 0;
a = x;
b = y;
p = 1;
q = 0;
r = 0;
s = 1;
while (1)
{
  if (!(b != 0))
    break;
  int c;
  int k;
  c = a;
  k = 0;
  while (1)
  {
    if (!(c >= b))
      break;
    int d;
    int v;
    d = 1;
    v = b;
    while (1)
    {
      if (!(b == ((x * q) + (y * s))))
        break;
      d = 2 * d;
      v = 2 * v;
    }

    c = c - v;
    k = k + d;
  }

  a = b;
  b = c;
  int temp;
  temp = p;
  p = q;
  q = temp - (q * k);
  temp = r;
  r = s;
  s = temp - (s * k);
}

return 0;
}


